import{_ as s,C as d,o as l,c as n,j as r,a,E as o,a2 as i}from"./chunks/framework.BxGh02fV.js";const v=JSON.parse('{"title":"Démarrer","description":"","frontmatter":{"title":"Démarrer"},"headers":[],"relativePath":"agent/demarrer.md","filePath":"agent/demarrer.md"}'),c={name:"agent/demarrer.md"};function u(f,e,m,p,_,h){const t=d("Ask");return l(),n("div",null,[e[0]||(e[0]=r("h1",{id:"demarrer",tabindex:"-1"},[a("Démarrer "),r("a",{class:"header-anchor",href:"#demarrer","aria-label":'Permalink to "Démarrer"'},"​")],-1)),e[1]||(e[1]=r("p",null,"Ce parcours sert à ouvrir un chantier : créer un projet neuf, prendre en charge un projet qui existe déjà, ou relier Effortless à votre agent. Vous y venez une fois par projet, ou une fois par machine pour le déploiement.",-1)),e[2]||(e[2]=r("h2",{id:"ce-que-vous-demandez-a-l-agent",tabindex:"-1"},[a("Ce que vous demandez à l'agent "),r("a",{class:"header-anchor",href:"#ce-que-vous-demandez-a-l-agent","aria-label":`Permalink to "Ce que vous demandez à l'agent"`},"​")],-1)),o(t,{say:"Crée un projet Effortless ici, avec le modèle tauri-react-tailwind.",verb:"effortless_init",family:"installation",args:'{"model_id":"tauri-react-tailwind"}'}),o(t,{say:"Quels modèles de stack existent ? Montre-moi le détail de rust.",verb:"effortless_stack_model_list",family:"stacks"}),o(t,{say:"Ce dépôt existe déjà : prépare sa migration vers Effortless, sans rien écrire pour l'instant.",verb:"effortless_migrate_init",family:"installation",args:'{"confirm":false}'}),o(t,{say:"Applique la migration.",verb:"effortless_migrate_apply",family:"installation",args:'{"dry_run":false}'}),o(t,{say:"Mets ce projet à niveau avec la version courante d'Effortless.",verb:"effortless_migrate",family:"installation",args:'{"confirm":true}'}),o(t,{say:"Range le code de la racine dans codebase/.",verb:"effortless_codebase_relocate",family:"installation",args:'{"dry_run":false}'}),o(t,{say:"Déploie Effortless dans mes agents.",verb:"effortless_deploy",family:"installation"}),e[3]||(e[3]=i('<h2 id="ce-que-fait-l-agent" tabindex="-1">Ce que fait l&#39;agent <a class="header-anchor" href="#ce-que-fait-l-agent" aria-label="Permalink to &quot;Ce que fait l&#39;agent&quot;">​</a></h2><h3 id="creer-un-projet-neuf" tabindex="-1">Créer un projet neuf <a class="header-anchor" href="#creer-un-projet-neuf" aria-label="Permalink to &quot;Créer un projet neuf&quot;">​</a></h3><ol><li><a href="/Effortless/reference/mcp/stacks.html#stack-model-list"><code>effortless_stack_model_list</code></a> liste les modèles disponibles (utilisable avant tout projet).</li><li><a href="/Effortless/reference/mcp/stacks.html#stack-model-show"><code>effortless_stack_model_show</code></a> détaille un modèle : variables, stratégie de build, cycle test/lint/run. Paramètre : <code>model_id</code>.</li><li><a href="/Effortless/reference/mcp/installation.html#init"><code>effortless_init</code></a> crée le projet dans le répertoire courant. Il passe <code>model_id</code> pour appliquer le modèle (arborescence et normes sous <code>.ai/ndd/</code>), et peut passer <code>project_name</code>, <code>description</code>, <code>context</code> (<code>greenfield</code>, <code>existing</code> ou <code>migration</code>). Il pose aussi <code>AGENTS.md</code> et <code>CLAUDE.md</code> (voir <a href="./">Avec un agent</a>).</li></ol><h3 id="reprendre-un-projet-existant" tabindex="-1">Reprendre un projet existant <a class="header-anchor" href="#reprendre-un-projet-existant" aria-label="Permalink to &quot;Reprendre un projet existant&quot;">​</a></h3><ol><li><a href="/Effortless/reference/mcp/installation.html#migrate-init"><code>effortless_migrate_init</code></a> analyse le dépôt. Avec <code>confirm: false</code> (défaut) c&#39;est un aperçu sans écriture ; avec <code>confirm: true</code> il pose la configuration, un épic, une story et <code>migration_plan.json</code>.</li><li><a href="/Effortless/reference/mcp/installation.html#migrate-apply"><code>effortless_migrate_apply</code></a> exécute les déplacements du plan. Avec <code>dry_run: true</code> c&#39;est un audit ; avec <code>dry_run: false</code> il déplace réellement les fichiers et écrit <code>migration_report.md</code>.</li><li><a href="/Effortless/reference/mcp/installation.html#codebase-relocate"><code>effortless_codebase_relocate</code></a>, si vous le voulez, range le code racine sous <code>codebase/&lt;stack&gt;/</code>. <code>dry_run</code> vaut <code>true</code> par défaut.</li></ol><h3 id="mettre-un-projet-a-niveau" tabindex="-1">Mettre un projet à niveau <a class="header-anchor" href="#mettre-un-projet-a-niveau" aria-label="Permalink to &quot;Mettre un projet à niveau&quot;">​</a></h3><p><a href="/Effortless/reference/mcp/installation.html#migrate"><code>effortless_migrate</code></a> rejoue les migrations jusqu&#39;au schéma courant. <code>confirm: false</code> (défaut) montre ce qui serait fait ; <code>confirm: true</code> l&#39;applique, avec des sauvegardes <code>.bak</code>. Les anciens verbes <a href="/Effortless/reference/mcp/installation.html#migrate-nomenclature"><code>effortless_migrate_nomenclature</code></a> et <a href="/Effortless/reference/mcp/installation.html#migrate-state"><code>effortless_migrate_state</code></a> sont dépréciés : ce sont des alias de <code>effortless_migrate</code>.</p><h3 id="deployer" tabindex="-1">Déployer <a class="header-anchor" href="#deployer" aria-label="Permalink to &quot;Déployer&quot;">​</a></h3><p><a href="/Effortless/reference/mcp/installation.html#deploy"><code>effortless_deploy</code></a> installe le serveur chez vos clients, le guide global et, pour Claude Code, la barre d&#39;état (voir <a href="./">Avec un agent</a>). <code>targets</code> limite les clients visés, <code>scope</code> choisit <code>user</code> (défaut) ou un projet, <code>grant_permissions: true</code> pose aussi les permissions du serveur. C&#39;est une action sur votre machine : l&#39;agent la lance à votre demande.</p><h2 id="ce-que-vous-obtenez" tabindex="-1">Ce que vous obtenez <a class="header-anchor" href="#ce-que-vous-obtenez" aria-label="Permalink to &quot;Ce que vous obtenez&quot;">​</a></h2><ul><li>Un projet avec <code>effortless.json</code>, <code>.effortless/</code>, l&#39;arbre de dossiers du modèle et, si le modèle en porte, les normes sous <code>.ai/ndd/</code>.</li><li><code>AGENTS.md</code> et <code>CLAUDE.md</code> à la racine.</li><li>Pour une reprise : <code>migration_plan.json</code>, puis <code>migration_report.md</code> une fois le plan appliqué.</li><li>À l&#39;écran : le projet s&#39;ouvre depuis le sélecteur d&#39;espaces de travail (<a href="/Effortless/guide/start.html">Ouvrir un espace de travail</a>) ; le déploiement se voit dans <strong>Préférences › MCP &amp; Skills</strong> (<a href="/Effortless/guide/preferences.html">Profil et préférences</a>).</li></ul><h2 id="quand-l-agent-est-refuse" tabindex="-1">Quand l&#39;agent est refusé <a class="header-anchor" href="#quand-l-agent-est-refuse" aria-label="Permalink to &quot;Quand l&#39;agent est refusé&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Situation</th><th>Ce que dit le refus</th><th>Ce qu&#39;il faut faire</th></tr></thead><tbody><tr><td>Un verbe de projet est appelé hors d&#39;un projet</td><td><code>mcp:racineProjetIntrouvable</code></td><td>Renseigner <code>EFFORTLESS_PROJECT</code> dans la configuration du serveur si le projet existe ailleurs ; sinon <code>effortless_init</code> en crée un ici.</td></tr><tr><td><code>EFFORTLESS_PROJECT</code> désigne un dossier sans projet</td><td><code>mcp:projetInexistantALEndroitDeclare</code></td><td>Appeler <code>effortless_init</code> à cet endroit : votre configuration n&#39;est pas en cause.</td></tr><tr><td><code>effortless_init</code> sur un dossier déjà initialisé</td><td><code>create:alreadyExists</code></td><td>Passer <code>force: true</code> pour écraser, ou choisir un autre répertoire.</td></tr><tr><td><code>effortless_init</code> avec un <code>model_id</code> inconnu</td><td><code>create:modelUnknown</code></td><td><code>effortless_stack_model_list</code> nomme les modèles disponibles. Rien n&#39;est écrit.</td></tr><tr><td><code>effortless_init</code> avec un nom fait d&#39;espaces</td><td><code>create:blankName</code></td><td>Passer un <code>project_name</code> avec au moins un caractère non blanc.</td></tr><tr><td><code>effortless_migrate_init</code> sur un projet déjà initialisé</td><td><code>adopt:alreadyInitialized</code></td><td>Passer <code>force: true</code> (une sauvegarde <code>.bak</code> est écrite).</td></tr><tr><td><code>effortless_migrate_apply</code> sans plan</td><td><code>adopt:planNotFound</code></td><td><code>effortless_migrate_init</code> écrit le plan de migration.</td></tr><tr><td><code>effortless_stack_model_show</code> avec un modèle inconnu</td><td>message « modèle … introuvable », sans code</td><td><code>effortless_stack_model_list</code> donne les identifiants valides.</td></tr><tr><td><code>effortless_codebase_relocate</code> en mode semi-auto</td><td>pas un refus : la réponse porte <code>gated: true</code> et aucun déplacement</td><td>Passer le projet en mode <code>full</code> avec <code>effortless_mode_set</code>.</td></tr></tbody></table><p><code>init</code> avec <code>force: true</code> vide aussi <code>.effortless/epics/</code>, <code>backlog.json</code> et <code>state.json</code> : l&#39;agent ne le fait qu&#39;à votre demande explicite.</p>',14))])}const b=s(c,[["render",u]]);export{v as __pageData,b as default};
